-- Keep existing stats and encounter identities; replace high-tier placeholder portraits.
UPDATE public.fc_monster_definitions SET name='嵴蚾',image_path='monsters/nascent_jibo.png',combat_note='栖息于内围寒晶洞窟的甲壳异兽，背甲布满螺旋纹，触须探查地脉，以灵矿碎晶为食。',weakness='甲壳接缝与腹部较薄弱。' WHERE id='wild_high_3' AND NOT is_boss;
INSERT INTO public.fc_monster_definitions(id,name,realm_index,region_depth,base_health,base_attack,base_defense,speed,weakness,combat_note,image_path) SELECT 'nascent_xuanni','旋猊',realm_index,region_depth,base_health,base_attack,base_defense,speed,'晶翼与核心之间的连接处。','徘徊于内围浮石峡谷的晶翼异兽，环状晶核悬于头部，借山风穿行，守护风属性灵草。','monsters/nascent_xuanni.png' FROM public.fc_monster_definitions WHERE id='wild_high_3' AND NOT is_boss;
UPDATE public.fc_monster_definitions SET name='溯蛉',image_path='monsters/outbody_suling.png',combat_note='栖息于核心古迹的多翼灵虫，薄翼带有水波纹，长须感知灵气流动，常伏于石阵附近。',weakness='薄翼与柔软腹节。' WHERE id='wild_high_4' AND NOT is_boss;
INSERT INTO public.fc_monster_definitions(id,name,realm_index,region_depth,base_health,base_attack,base_defense,speed,weakness,combat_note,image_path) SELECT 'outbody_bituo','罴鼍',realm_index,region_depth,base_health,base_attack,base_defense,speed,'骨肢关节与腹部。','盘踞核心废墟的厚皮巨兽，背部骨肢支撑庞大身躯，地面留下暗色黏液，守护古迹灵草。','monsters/outbody_bituo.png' FROM public.fc_monster_definitions WHERE id='wild_high_4' AND NOT is_boss;
UPDATE public.fc_monster_definitions SET name='嵫隹',image_path='monsters/deity_zizhui.png',combat_note='游荡于核心高空的环骨异兽，层层骨环围绕中枢旋转，吸纳雷云与星辉，守护高阶灵草。',weakness='骨环间露出的中枢。' WHERE id='wild_high_5' AND NOT is_boss;
INSERT INTO public.fc_monster_definitions(id,name,realm_index,region_depth,base_health,base_attack,base_defense,speed,weakness,combat_note,image_path) SELECT 'deity_bigui','赑蛫',realm_index,region_depth,base_health,base_attack,base_defense,speed,'张口时暴露的口腔与足根。','栖息于核心深渊的巨口异兽，褶皱厚甲覆盖全身，多足攀附岩壁，捕食靠近洞穴的生灵。','monsters/deity_bigui.png' FROM public.fc_monster_definitions WHERE id='wild_high_5' AND NOT is_boss;
